ged-person-profile-coldstart-20261013/review-material-0.txt\": \"\\\"\\\"\\\"TWA.12 / 168 — normalize email/phone to canonical membership subject.\\\"\\\"\\\"\\nfrom __future__ import annotations\\n\\nimport re\\nfrom typing import Any\\n\\nfrom aos_api.db import connect_read_only\\nfrom aos_api.logging_facade import get_logger\\n\\nlog = get_logger(\\\"aos-api.person-identity\\\")\\n\\n_EMAIL_RE = re.compile(r\\\"^[^@\\\\s]+@[^@\\\\s]+\\\\.[^@\\\\s]+$\\\")\\n_PHONE_DIGITS = re.compile(r\\\"[^\\\\d+]\\\")\\n\\n# subject -> profile\\n_PERSONS: dict[str, dict[str, Any]] = {}\\n\\n\\ndef load_profiles_from_db(*, strict: bool = False) -> int:\\n    \\\"\\\"\\\"Hydrate existing profiles without legacy seeds or database writes.\\\"\\\"\\\"\\n    global _PERSONS\\n    from aos_api.tenant_catalog import persistence_enabled\\n\\n    if not persistence_enabled():\\n        return 0\\n    try:\\n        with connect_read_only(inherit_scope=False, platform_role=True) as conn:\\n            rows = conn.execute(\\n                \\\"SELECT subject, email, phone, display_name, title \\\"\\n                \\\"FROM twa_person_profile ORDER BY subject\\\"\\n            ).fetchall()\\n        loaded = {}\\n        for row in rows:\\n            subject = row[\\\"subject\\\"]\\n            if not isinstance(subject, str) or not subject.strip():\\n                raise ValueError(\\\"invalid persisted person subject\\\")\\n            loaded[subject] = {\\n                \\\"subject\\\": subject,\\n                \\\"email\\\": row[\\\"email\\\"],\\n                \\\"phone\\\": row[\\\"phone\\\"],\\n                \\\"displayName\\\": row[\\\"display_name\\\"],\\n                \\\"title\\\": row[\\\"title\\\"],\\n            }\\n    except Exception:  # noqa: BLE001 — compatibility mode retains prior cache\\n        if strict:\\n            raise\\n        log.warning(\\\"person_profile_load_fail\\\", exc_info=True)\\n        return 0\\n    # Publish only after the complete read and validation succeeds.\\n    _PERSONS = loaded\\n    log.info(\\\"person_profile_load count=%s\\\", len(loaded))\\n    return len(loaded)\\n\\n\\ndef reset_person_store() -> None:\\n    _PERSONS.clear()\\n    from aos_api import twa_pg\\n\\n    twa_pg.truncate_persons()\\n\\n\\ndef upsert_person_profile(\\n    subject: str,\\n    *,\\n    email: str | None = None,\\n    phone: str | None = None,\\n    display_name: str | None = None,\\n    title: str | None = None,\\n) -> dict[str, Any]:\\n    sub = (subject or \\\"\\\").strip()\\n    if not sub:\\n        raise ValueError(\\\"subject required\\\")\\n    prev = dict(_PERSONS.get(sub, {}))\\n    if email:\\n        prev[\\\"email\\\"] = normalize_email(email)\\n    if phone:\\n        prev[\\\"phone\\\"] = normalize_phone(phone)\\n    if display_name:\\n        prev[\\\"displayName\\\"] = display_name.strip()\\n    if title:\\n        prev[\\\"title\\\"] = title.strip()\\n    prev[\\\"subject\\\"] = sub\\n    _PERSONS[sub] = prev\\n    from aos_api import twa_pg\\n\\n    twa_pg.upsert_person(prev)\\n    return dict(prev)\\n\\n\\ndef seed_dev_persons() -> None:\\n    \\\"\\\"\\\"Bind human profiles to Dev seed subjects (alice / user:dev / bob).\\\"\\\"\\\"\\n    upsert_person_profile(\\n        \\\"alice\\\",\\n        email=\\\"alice@acme.example\\\",\\n        phone=\\\"+8613800138000\\\",\\n        display_name=\\\"艾丽斯\\\",\\n        title=\\\"组织所有者\\\",\\n    )\\n    upsert_person_profile(\\n        \\\"user:dev\\\",\\n        email=\\\"dev@local.aos\\\",\\n        phone=\\\"+8613900139000\\\",\\n        display_name=\\\"本机开发者\\\",\\n        title=\\\"本机 Bearer 登录账号\\\",\\n    )\\n    upsert_person_profile(\\n        \\\"bob\\\",\\n        email=\\\"bob@acme.example\\\",\\n        phone=\\\"+8613700137000\\\",\\n        display_name=\\\"鲍勃\\\",\\n        title=\\\"运营查看者\\\",\\n    )\\n\\n\\ndef normalize_email(raw: str) -> str:\\n    addr = (raw or \\\"\\\").strip().lower()\\n    if not addr or not _EMAIL_RE.match(addr):\\n        raise ValueError(\\\"invalid email\\\")\\n    return addr\\n\\n\\ndef normalize_phone(raw: str) -> str:\\n    s = _PHONE_DIGITS.sub(\\\"\\\", (raw or \\\"\\\").strip())\\n    if not s:\\n        raise ValueError(\\\"invalid phone\\\")\\n    if s.startswith(\\\"00\\\"):\\n        s = \\\"+\\\" + s[2:]\\n    if s.isdigit() and len(s) == 11 and s.startswith(\\\"1\\\"):\\n        s = \\\"+86\\\" + s\\n    if s.isdigit() and not s.startswith(\\\"+\\\"):\\n        s = \\\"+\\\" + s\\n    if not s.startswith(\\\"+\\\") or len(re.sub(r\\\"\\\\D\\\", \\\"\\\", s)) < 8:\\n        raise ValueError(\\\"invalid phone\\\")\\n    return s\\n\\n\\ndef subject_from_email(email: str) -> str:\\n    return f\\\"email:{normalize_email(email)}\\\"\\n\\n\\ndef subject_from_phone(phone: str) -> str:\\n    return f\\\"phone:{normalize_phone(phone)}\\\"\\n\\n\\ndef resolve_member_identity(\\n    *,\\n    subject: str | None = None,\\n    email: str | None = None,\\n    phone: str | None = None,\\n    display_name: str | None = None,\\n) -> dict[str, Any]:\\n    \\\"\\\"\\\"Prefer email > phone > subject. Returns canonical subject + profile fields.\\\"\\\"\\\"\\n    from aos_api import account_link as alink\\n\\n    sub = (subject or \\\"\\\").strip()\\n    em = (email or \\\"\\\").strip()\\n    ph = (phone or \\\"\\\").strip()\\n    # 200m — if contact is linked to an IdP subject, use that subject\\n    linked = None\\n    try:\\n        linked = alink.find_subject_by_contact(\\n            email=em or None,\\n            phone=ph or None,\\n        )\\n    except ValueError:\\n        linked = None\\n    if linked:\\n        existing = _PERSONS.get(linked, {})\\n        profile = {\\n            \\\"subject\\\": linked,\\n            \\\"email\\\": normalize_email(em) if em else existing.get(\\\"email\\\"),\\n            \\\"phone\\\": normalize_phone(ph) if ph else existing.get(\\\"phone\\\"),\\n            \\\"displayName\\\": (display_name or \\\"\\\").strip()\\n            or existing.get(\\\"displayName\\\")\\n            or linked,\\n            \\\"kind\\\": \\\"linked\\\",\\n        }\\n    elif em:\\n        canon = subject_from_email(em)\\n        profile = {\\n            \\\"subject\\\": canon,\\n            \\\"email\\\": normalize_email(em),\\n            \\\"phone\\\": _PERSONS.get(canon, {}).get(\\\"phone\\\"),\\n            \\\"displayName\\\": (display_name or \\\"\\\").strip() or normalize_email(em),\\n            \\\"kind\\\": \\\"email\\\",\\n        }\\n    elif ph:\\n        canon = subject_from_phone(ph)\\n        e164 = normalize_phone(ph)\\n        profile = {\\n            \\\"subject\\\": canon,\\n            \\\"email\\\": _PERSONS.get(canon, {}).get(\\\"email\\\"),\\n            \\\"phone\\\": e164,\\n            \\\"displayName\\\": (display_name or \\\"\\\").strip() or e164,\\n            \\\"kind\\\": \\\"phone\\\",\\n        }\\n    elif sub:\\n        existing = _PERSONS.get(sub, {})\\n        profile = {\\n            \\\"subject\\\": sub,\\n            \\\"email\\\": existing.get(\\\"email\\\"),\\n            \\\"phone\\\": existing.get(\\\"phone\\\"),\\n            \\\"displayName\\\": (display_name or \\\"\\\").strip()\\n            or existing.get(\\\"displayName\\\")\\n            or sub,\\n            \\\"kind\\\": \\\"subject\\\",\\n        }\\n    else:\\n        raise ValueError(\\\"email, phone, or subject required\\\")\\n\\n    prev = _PERSONS.get(profile[\\\"subject\\\"], {})\\n    merged = {**prev, **{k: v for k, v in profile.items() if v}}\\n    _PERSONS[profile[\\\"subject\\\"]] = merged\\n    from aos_api import twa_pg\\n\\n    twa_pg.upsert_person(merged)\\n    log.info(\\n        \\\"person_resolve subject=%s kind=%s\\\",\\n        profile[\\\"subject\\\"],\\n        profile[\\\"kind\\\"],\\n    )\\n    return merged\\n\\n\\ndef get_profile(subject: str) -> dict[str, Any]:\\n    sub = (subject or \\\"\\\").strip()\\n    prof = dict(_PERSONS.get(sub, {}))\\n    if not prof:\\n        return {\\n            \\\"subject\\\": sub,\\n            \\\"displayName\\\": sub,\\n            \\\"displayLabel\\\": sub,\\n            \\\"email\\\": None,\\n            \\\"phone\\\": None,\\n            \\\"title\\\": None,\\n        }\\n    out = {\\n        \\\"subject\\\": sub,\\n        \\\"displayName\\\": prof.get(\\\"displayName\\\") or sub,\\n        \\\"displayLabel\\\": prof.get(\\\"displayName\\\")\\n        or prof.get(\\\"email\\\")\\n        or prof.get(\\\"phone\\\")\\n        or sub,\\n        \\\"email\\\": prof.get(\\\"email\\\"),\\n        \\\"phone\\\": prof.get(\\\"phone\\\"),\\n        \\\"title\\\": prof.get(\\\"title\\\"),\\n    }\\n    return out\\n\\n\\ndef update_own_profile(\\n    subject: str,\\n    *,\\n    display_name: str | None = None,\\n    email: str | None = None,\\n    phone: str | None = None,\\n    title: str | None = None,\\n) -> dict[str, Any]:\\n    \\\"\\\"\\\"Update profile for login subject. Does NOT change membership subject key.\\\"\\\"\\\"\\n    sub = (subject or \\\"\\\").strip()\\n    if not sub:\\n        raise ValueError(\\\"subject required\\\")\\n    prev = dict(_PERSONS.get(sub, {\\\"subject\\\": sub}))\\n    if display_name is not None:\\n        prev[\\\"displayName\\\"] = display_name.strip() or sub\\n    if title is not None:\\n        t = title.strip()\\n        if t:\\n            prev[\\\"title\\\"] = t\\n        else:\\n            prev.pop(\\\"title\\\", None)\\n    if email is not None:\\n        if email.strip() == \\\"\\\":\\n            prev.pop(\\\"email\\\", None)\\n        else:\\n            prev[\\\"email\\\"] = normalize_email(email)\\n    if phone is not None:\\n        if phone.strip() == \\\"\\\":\\n            prev.pop(\\\"phone\\\", None)\\n        else:\\n            prev[\\\"phone\\\"] = normalize_phone(phone)\\n    prev[\\\"subject\\\"] = sub\\n    _PERSONS[sub] = prev\\n    from aos_api import twa_pg\\n\\n    twa_pg.upsert_person(prev)\\n    log.info(\\\"person_profile_update subject=%s\\\", sub)\\n    return get_profile(sub)\\n\\n\\ndef enrich_member_row(row: dict[str, Any]) -> dict[str, Any]:\\n    sub = row.get(\\\"subject\\\") or \\\"\\\"\\n    prof = _PERSONS.get(sub, {})\\n    out = dict(row)\\n    if prof.get(\\\"email\\\"):\\n        out[\\\"email\\\"] = prof[\\\"email\\\"]\\n    if prof.get(\\\"phone\\\"):\\n        out[\\\"phone\\\"] = prof[\\\"phone\\\"]\\n    if prof.get(\\\"title\\\"):\\n        out[\\\"title\\\"] = prof[\\\"title\\\"]\\n    if prof.get(\\\"displayName\\\"):\\n        out[\\\"displayName\\\"] = prof[\\\"displayName\\\"]\\n    label = (\\n        prof.get(\\\"displayName\\\")\\n        or prof.get(\\\"email\\\")\\n        or prof.get(\\\"phone\\\")\\n        or sub\\n    )\\n    out[\\\"displayLabel\\\"] = label\\n    return out\\n\", \".evidence/qyh-managed-person-profile-coldstart-20261013/review-material-1.txt\": \"\\\"\\\"\\\"Boot / schema for Org · Workspace · Membership persistence (164 v1.1).\\\"\\\"\\\"\\nfrom __future__ import annotations\\n\\nfrom aos_api.db import connect, connect_platform\\nfrom aos_api.logging_facade import get_logger\\n\\nlog = get_logger(\\\"aos-api.tenant-catalog\\\")\\n\\n_schema_ready = False\\n\\n# Created by alembic migrations. The runtime login has USAGE but not CREATE on\\n# ``public`` (verified: has_schema_privilege(..., 'public', 'CREATE') = false),\\n# so any DDL attempt fails even with IF NOT EXISTS — PostgreSQL checks the\\n# privilege before it checks object existence. Probe instead of issuing DDL.\\n_CATALOG_TABLES = (\\\"meta_org\\\", \\\"meta_workspace\\\", \\\"meta_membership\\\")\\n\\n\\ndef persistence_enabled() -> bool:\\n    \\\"\\\"\\\"Return whether the tenant catalog may read/write PostgreSQL.\\n\\n    ``AOS_TWA_STORE=memory`` is the unit-test/in-process boundary and must not\\n    silently mutate the shared ``meta_*`` catalog.  ``auto`` and ``pg`` keep\\n    the existing durable behavior.\\n    \\\"\\\"\\\"\\n    from aos_api import twa_pg\\n\\n    return twa_pg.enabled()\\n\\n\\ndef _catalog_tables_present() -> bool:\\n    \\\"\\\"\\\"True when every catalog table already exists in this database.\\\"\\\"\\\"\\n\\n    try:\\n        with connect_platform() as conn:\\n            row = conn.execute(\\n                \\\"\\\"\\\"\\n                SELECT count(*) AS n\\n                FROM pg_class\\n                WHERE relkind = 'r' AND relname = ANY(%s)\\n                \\\"\\\"\\\",\\n                (list(_CATALOG_TABLES),),\\n            ).fetchone()\\n    except Exception:  # noqa: BLE001 — treat probe failure as \\\"not ready\\\"\\n        log.debug(\\\"tenant_catalog_probe_skip\\\", exc_info=True)\\n        return False\\n    return int(row[\\\"n\\\"]) == len(_CATALOG_TABLES)\\n\\n\\ndef ensure_tenant_catalog_schema() -> None:\\n    global _schema_ready\\n    if not persistence_enabled():\\n        return\\n    if _schema_ready:\\n        return\\n    if _catalog_tables_present():\\n        # Normal production path: migrations own the schema, the runtime role\\n        # only reads/writes rows. Short-circuit before any DDL so a privilege\\n        # error can never be mistaken for \\\"persistence unavailable\\\".\\n        _schema_ready = True\\n        return\\n    with connect(inherit_scope=False) as conn:\\n        conn.execute(\\n            \\\"\\\"\\\"\\n            CREATE TABLE IF NOT EXISTS meta_org (\\n              id TEXT PRIMARY KEY,\\n              name TEXT NOT NULL,\\n              kind TEXT NOT NULL DEFAULT 'standard',\\n              join_policy TEXT NOT NULL DEFAULT 'invite_or_apply',\\n              discoverable BOOLEAN NOT NULL DEFAULT TRUE,\\n              updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()\\n            )\\n            \\\"\\\"\\\"\\n        )\\n        conn.execute(\\n            \\\"\\\"\\\"\\n            CREATE TABLE IF NOT EXISTS meta_workspace (\\n              org_id TEXT NOT NULL,\\n              project_id TEXT NOT NULL,\\n              name TEXT NOT NULL,\\n              deletable BOOLEAN NOT NULL DEFAULT TRUE,\\n              kind TEXT NOT NULL DEFAULT 'custom',\\n              updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),\\n              PRIMARY KEY (org_id, project_id)\\n            )\\n            \\\"\\\"\\\"\\n        )\\n        conn.execute(\\n            \\\"\\\"\\\"\\n            CREATE TABLE IF NOT EXISTS meta_membership (\\n              org_id TEXT NOT NULL,\\n              project_id TEXT NOT NULL,\\n              subject TEXT NOT NULL,\\n              role TEXT NOT NULL,\\n              updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),\\n              PRIMARY KEY (org_id, project_id, subject)\\n            )\\n            \\\"\\\"\\\"\\n        )\\n        conn.commit()\\n    _schema_ready = True\\n    log.info(\\\"tenant_catalog_schema_ready\\\")\\n\\n\\ndef boot_tenant_catalogs(*, read_only: bool = False) -> None:\\n    \\\"\\\"\\\"Load PG → memory only; do **not** auto-seed dev-org.\\n\\n    Non-legacy startup uses read_only=True: require migrated tables, load in\\n    read-only transactions and propagate failures instead of starting with empty\\n    caches that could trigger request-time bootstrap writes.\\n\\n    dev-org / dev-project / 默认人员等测试数据已迁移到 ``aos_api.demo.seed_test_org``。\\n    企业上线后由管理员自建组织；开发/测试显式执行 ``seed_test_org()``。\\n    \\\"\\\"\\\"\\n    if not persistence_enabled():\\n        log.info(\\\"tenant_catalog_boot_skipped store=memory\\\")\\n        return\\n    if read_only:\\n        if not _catalog_tables_present():\\n            raise RuntimeError(\\\"TENANT_CATALOG_SCHEMA_UNAVAILABLE\\\")\\n    else:\\n        ensure_tenant_catalog_schema()\\n    from aos_api import membership as mem\\n    from aos_api import orgs as org_store\\n    from aos_api import workspaces_catalog as ws_cat\\n\\n    if read_only:\\n        org_store.load_orgs_from_db(strict=True)\\n        ws_cat.load_workspaces_from_db(strict=True)\\n        mem.load_memberships_from_db(strict=True)\\n        from aos_api.person_identity import load_profiles_from_db\\n\\n        load_profiles_from_db(strict=True)\\n    else:\\n        org_store.load_orgs_from_db()\\n        ws_cat.load_workspaces_from_db()\\n        mem.load_memberships_from_db()\\n    log.info(\\n        \\\"tenant_catalog_booted orgs=%s workspaces=%s members=%s\\\",\\n        org_store.org_count(),\\n        ws_cat.workspace_count(),\\n        mem.membership_count(),\\n    )\\n\", \".evidence/qyh-managed-person-profile-coldstart-20261013/review-material-2.txt\": \"from contextlib import contextmanager\\n\\nimport pytest\\n\\nfrom aos_api import db, person_identity as person, tenant_catalog\\n\\n\\n@pytest.fixture\\ndef profiles(monkeypatch):\\n    monkeypatch.setattr(tenant_catalog, 'persistence_enabled', lambda: True)\\n    monkeypatch.setattr(person, '_PERSONS', {})\\n    return monkeypatch\\n\\n\\ndef test_persisted_profile_survives_cold_cache_with_native_readonly_connection(profiles):\\n    with db.connect_platform() as conn:\\n        assert conn.info.dbname.startswith('aos_test_')\\n        conn.execute(\\\"INSERT INTO twa_person_profile(subject,display_name,title) VALUES(%s,%s,%s)\\\",\\n                     ('human:cold-profile-test', 'Persisted administrator', 'Administrator'))\\n        conn.commit()\\n    assert person.get_profile('human:cold-profile-test')['displayName'] == 'human:cold-profile-test'\\n    observed = []\\n    @contextmanager\\n    def readonly(**kwargs):\\n        assert kwargs == {'inherit_scope': False, 'platform_role': True}\\n        with db.connect_read_only(**kwargs) as conn:\\n            assert conn.execute('SHOW transaction_read_only').fetchone()['transaction_read_only'] == 'on'\\n            observed.append(True)\\n            yield conn\\n    profiles.setattr(person, 'connect_read_only', readonly, raising=False)\\n    assert person.load_profiles_from_db(strict=True) >= 1\\n    assert observed == [True]\\n    assert person.get_profile('human:cold-profile-test')['displayName'] == 'Persisted administrator'\\n    assert person.get_profile('human:cold-profile-test')['email'] is None\\n    with db.connect_platform() as conn:\\n        assert conn.execute(\\\"SELECT count(*) AS n FROM twa_person_profile WHERE subject=%s\\\", ('human:cold-profile-test',)).fetchone()['n'] == 1\\n\\n\\ndef test_failed_strict_load_preserves_existing_cache(profiles):\\n    person._PERSONS['preserved'] = {'subject': 'preserved', 'displayName': 'Existing'}\\n    @contextmanager\\n    def unavailable(**kwargs):\\n        raise RuntimeError('profile catalog unavailable')\\n        yield\\n    profiles.setattr(person, 'connect_read_only', unavailable, raising=False)\\n    with pytest.raises(RuntimeError, match='profile catalog unavailable'):\\n        person.load_profiles_from_db(strict=True)\\n    assert person.get_profile('preserved')['displayName'] == 'Existing'\\n    assert person.load_profiles_from_db() == 0\\n    assert person.get_profile('preserved')['displayName'] == 'Existing'\\n\\n\\ndef test_memory_mode_never_connects_or_replaces_profile(profiles):\\n    profiles.setattr(tenant_catalog, 'persistence_enabled', lambda: False)\\n    person._PERSONS['preserved'] = {'subject': 'preserved', 'displayName': 'Existing'}\\n    def forbidden(**kwargs):\\n        raise AssertionError('memory mode must never connect')\\n    profiles.setattr(person, 'connect_read_only', forbidden, raising=False)\\n    assert person.load_profiles_from_db(strict=True) == 0\\n    assert person.get_profile('preserved')['displayName'] == 'Existing'\\n\\n\\ndef test_invalid_row_never_publishes_a_partial_profile_cache(profiles):\\n    person._PERSONS['preserved'] = {'subject': 'preserved', 'displayName': 'Existing'}\\n    class Connection:\\n        def execute(self, query):\\n            assert query.startswith('SELECT ') and 'FROM twa_person_profile' in query\\n            return self\\n        def fetchall(self):\\n            return [dict(subject='new', display_name='New', email=None, phone=None, title=None),\\n                    dict(subject='', display_name='Invalid', email=None, phone=None, title=None)]\\n    @contextmanager\\n    def readonly(**kwargs):\\n        yield Connection()\\n    profiles.setattr(person, 'connect_read_only', readonly)\\n    with pytest.raises(ValueError, match='invalid persisted person subject'):\\n        person.load_profiles_from_db(strict=True)\\n    assert set(person._PERSONS) == {'preserved'}\\n\", \".evidence/qyh-managed-person-profile-coldstart-20261013/review-material-3.txt\": \"from contextlib import contextmanager\\nimport ast\\nfrom pathlib import Path\\nfrom types import SimpleNamespace\\n\\nimport pytest\\n\\nfrom aos_api import membership, orgs, person_identity, tenant_catalog, workspaces_catalog\\n\\n\\n@pytest.fixture\\ndef catalog(monkeypatch):\\n    monkeypatch.setattr(tenant_catalog, 'persistence_enabled', lambda: True)\\n    monkeypatch.setattr(tenant_catalog, '_catalog_tables_present', lambda: True)\\n    for module, name in [(orgs, '_ORGS'), (workspaces_catalog, '_WS'), (membership, '_MEMBERS'), (person_identity, '_PERSONS')]:\\n        monkeypatch.setattr(module, name, {})\\n    def forbidden(*args, **kwargs):\\n        raise AssertionError('read-only boot/query must not persist or run DDL')\\n    monkeypatch.setattr(tenant_catalog, 'ensure_tenant_catalog_schema', forbidden)\\n    monkeypatch.setattr(orgs, '_persist_org', forbidden)\\n    monkeypatch.setattr(workspaces_catalog, '_persist_ws', forbidden)\\n    monkeypatch.setattr(membership, '_persist_member', forbidden)\\n    return monkeypatch\\n\\n\\ndef test_readonly_boot_preserves_existing_viewer_and_queries_never_write(catalog):\\n    rows = {\\n        'meta_org': [dict(id='org-org', name='existing', kind='saas', join_policy='invite_only', discoverable=False)],\\n        'meta_workspace': [dict(org_id='org-org', project_id='dev-project', name='existing workspace', deletable=False, kind='custom')],\\n        'meta_membership': [dict(org_id='org-o